pipeline {
    agent any

    environment {
        REMOTE_HOST = '20.48.1.68' // 远程服务器地址
        REMOTE_USER = 'root' // 远程服务器用户名
        REMOTE_CREDENTIALS_ID = 'server-18-credentials-id' // Jenkins中保存的远程服务器SSH凭证ID
        REMOTE_ADDRESS = '/data/soft/sjzydj/test/'  //远程服务器web文件地址
        TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('UTC+8'))
    }

    stages {
        stage('Git') {
            steps {
                echo "Trying to checkout code from gitlab branch: ${params.Branch}"
                checkout scmGit(branches: [[name: "${params.Branch}"]], extensions: [], userRemoteConfigs: [[credentialsId: 'SSH-KEY-FOR-GITLAB', url: '${GIALAB_ADDRESS}/front/PublicDataPlatform/data-resource-registration-web']])
            }
        }

        stage('Npm Install') {
            steps {
                //  nvm("v20.13.1") {
                 nvm("v22.20.0") {
                    sh 'node -v'
                    sh 'pnpm -v'
                    sh 'pnpm install --no-frozen-lockfile'
                }


            }
        }

        stage('Npm Build') {
            steps {
        //         // sh 'npm run build'
        //         nvm("v18.20.2") {
                    sh 'pnpm run build:test'
        //         }

            }
        }


        stage('Deploy to Remote') {
            steps {
                script {
                    sh 'pwd'
                    sh 'tar -zcvf ./dist-portal.tar.gz ./dist-test-client'
                    sh 'scp dist-portal.tar.gz root@${REMOTE_HOST}:${REMOTE_ADDRESS} ' 

                    sh 'tar -zcvf ./dist-manage.tar.gz ./dist-test-admin'
                    sh 'scp dist-manage.tar.gz root@${REMOTE_HOST}:${REMOTE_ADDRESS} ' 

                    sshagent([REMOTE_CREDENTIALS_ID]) {
                        sh """
                            ssh ${REMOTE_USER}@${REMOTE_HOST} '
                            cd ${REMOTE_ADDRESS}  &&

                            mv ./dist-portal.tar.gz ./portal  &&
                            mv ./dist-manage.tar.gz ./manage  &&

                            cd ./portal  &&
                            if [ -d "dist/" ];then
                                mv dist/ dist-${TIMESTAMP}/
                            fi  &&
                            tar -zxvf dist-portal.tar.gz  &&
                            rm -f dist-portal.tar.gz &&
                            mv dist-test-client/ dist/ &&

                            cd ${REMOTE_ADDRESS}  &&
                            cd ./manage  &&
                            if [ -d "dist/" ];then
                                mv dist/ dist-${TIMESTAMP}/
                            fi  &&
                            tar -zxvf dist-manage.tar.gz  &&
                            rm -f dist-manage.tar.gz &&
                            mv dist-test-admin/ dist/ 
                            '
                           """
                    }
                }
            }
        }


    }
}
